import csv
import json
import sys


class ExportError(Exception):
    pass


def export_all(jobs):
    for job in jobs:
        try:
            with open(job["destination"], "x", newline="", encoding="utf-8") as stream:
                writer = csv.writer(stream, lineterminator="\n")
                writer.writerow(["name", "quantity"])
                writer.writerows((item["name"], item["quantity"]) for item in job["items"])
        except OSError as error:
            raise ExportError(f"Export stopped at {job['destination']}: {error}") from error


if __name__ == "__main__":
    try:
        export_all(json.loads(open(sys.argv[1], encoding="utf-8").read()))
    except ExportError as error:
        print(str(error), file=sys.stderr)
        raise SystemExit(2)
